-- Real ReaderUI navigation using breakpoints generated by the existing Desktop code.
require("setupkoenv")
local json = require("json")
local root = "../../../../.work/results/position-probe"
local settings = assert(os.getenv("KO_HOME"))
local function read_json(name)
    local file = assert(io.open(root .. "/" .. name, "rb"))
    local data = json.decode(file:read("*a")); file:close(); return data
end
local manifest, oracle = read_json("manifest.json"), read_json("kotlin-oracle.json")
G_defaults = require("luadefaults"):open(settings .. "/defaults.lua")
G_reader_settings = require("luasettings"):open(settings .. "/settings.lua")
G_reader_settings:saveSetting("document_metadata_folder", "doc")
G_reader_settings:saveSetting("txt_preformatted", 1)
G_reader_settings:saveSetting("font_face", "FreeSans")
G_reader_settings:saveSetting("followed_link_marker", false)
require("logger"):setLevel(require("logger").levels.warn)
einkfb = require("ffi/framebuffer"); einkfb.dummy = true
local Device = require("device")
Device.screen:init(); Device.input.dummy = true
require("document/canvascontext"):init(Device)
local Loader = require("pluginloader")
Loader.enabled_plugins, Loader.disabled_plugins, Loader.loaded_plugins = {}, {}, {}
local path = "../../../../experiments/flonovel.koplugin"
Loader:_load({ { name = "flonovel", path = path, main = path .. "/main.lua", meta = path .. "/_meta.lua" } })
local ReaderUI, Registry = require("apps/reader/readerui"), require("document/documentregistry")
local UIManager, Event = require("ui/uimanager"), require("ui/event")
local bulk_mode = os.getenv("FLONOVEL_PROBE_BULK") == "1"
local result_prefix = bulk_mode and "bulk-" or ""
local Map = dofile("../../../../experiments/" .. (bulk_mode and "bulk_position_map.lua" or "txt_position_map.lua"))
local Chapters = dofile("../../../../experiments/chapter_probe.lua")
local output = { tests = {}, observations = {}, scope = "PC_ReaderUI_synthetic_long_document" }
local function check(name, success, detail)
    output.tests[#output.tests + 1] = { name = name, passed = not not success, detail = detail }
end
local function same_points(actual, expected)
    if #actual ~= #expected then return false end
    for index, point in ipairs(expected) do if actual[index] ~= point then return false end end
    return true
end
local ui = ReaderUI:new{ dimen = Device.screen:getSize(), document = Registry:openDocument(settings .. "/inputs/reader_long.txt") }
UIManager:show(ui)
collectgarbage("collect")
local memory_before, started = collectgarbage("count"), os.clock()
local map, err = Map.build(ui.document, manifest.reader_text)
output.map_cpu_seconds, output.lua_heap_growth_kib = os.clock() - started, collectgarbage("count") - memory_before
check("long_source_map", map ~= nil, err)
local points, chapters = Chapters.breakpoints(manifest.reader_text, 4)
check("chapter_count_matches_kotlin", #chapters == #oracle.chapters)
check("breakpoints_match_kotlin", same_points(points, oracle.breakpoints))
for index, chapter in ipairs(chapters) do
    check("chapter_offset_" .. index, chapter.offset == oracle.chapters[index].offset)
end
check("source_length_matches_kotlin", map and map.length == oracle.reader_length)
for name, text in pairs(manifest.jump_cases) do
    local actual = Chapters.breakpoints(text, 4)
    check("jump_case_matches_kotlin_" .. name, same_points(actual, oracle.jump_cases[name]))
end
check("multiple_pages", ui.document:getPageCount() > 5, ui.document:getPageCount())
output.pages, output.source_units, output.nodes = ui.document:getPageCount(), oracle.reader_length, map and #map.nodes
local function current() return map and map:from_xpointer(ui.rolling:getLastProgress()) end
local function jump(offset)
    local xp = assert(map:to_exact_boundary(offset))
    ui:handleEvent(Event:new("GotoXPointer", xp))
end
if map then
    ui.flonovel.probe_map, ui.flonovel.probe_points = map, points
    jump(0)
    for index, expected in ipairs(oracle.breakpoints) do
        ui:handleEvent(Event:new("FloNovelProbeNext"))
        check("next_subdivision_" .. index, current() == expected, { expected = expected, actual = current(), error = ui.flonovel.navigation_error })
    end
    ui:handleEvent(Event:new("FloNovelProbeNext"))
    check("next_at_last_does_not_advance", current() == oracle.reader_length and ui.flonovel.navigation_error == "no_subdivision_in_direction")
    for index = #oracle.breakpoints - 1, 1, -1 do
        ui:handleEvent(Event:new("FloNovelProbePrevious"))
        check("previous_subdivision_" .. index, current() == oracle.breakpoints[index])
    end
    jump(0)
    ui:handleEvent(Event:new("FloNovelProbePrevious"))
    check("previous_at_start_does_not_advance", current() == 0 and ui.flonovel.navigation_error == "no_subdivision_in_direction")
    for _, direction in ipairs({ 1, 1, 1, 1, -1, -1, -1, -1 }) do
        local before = current()
        ui:handleEvent(Event:new("GotoViewRel", direction))
        local after = current()
        output.observations[#output.observations + 1] = { direction = direction, before = before, after = after,
            xpointer = ui.rolling:getLastProgress() }
        check("page_anchor_mapped_" .. #output.observations, after ~= nil)
        check("page_direction_" .. #output.observations, before and after and (direction > 0 and after > before or direction < 0 and after < before))
    end
    jump(points[5])
    ui:handleEvent(Event:new("SetFontSize", 32))
    check("long_reflow_retains_anchor", current() == points[5])
    UIManager:forceRePaint()
    Device.screen:shot(root .. "/" .. result_prefix .. "long-reader-ui.png")
end
ui:onClose()
local tiny = ReaderUI:new{ dimen = Device.screen:getSize(), document = Registry:openDocument(settings .. "/inputs/reader_tiny.txt") }
UIManager:show(tiny)
tiny:handleEvent(Event:new("SetFontSize", 12))
local tiny_map = Map.build(tiny.document, manifest.tiny_text)
local tiny_points = Chapters.breakpoints(manifest.tiny_text, 4)
check("tiny_map", tiny_map ~= nil)
check("tiny_breakpoints_match_kotlin", same_points(tiny_points, oracle.tiny_breakpoints))
local same_page = 0
if tiny_map then
    tiny.flonovel.probe_map, tiny.flonovel.probe_points = tiny_map, tiny_points
    tiny:handleEvent(Event:new("GotoXPointer", assert(tiny_map:to_exact_boundary(0))))
    for index, expected in ipairs(oracle.tiny_breakpoints) do
        local previous_page = tiny.rolling.current_page
        tiny:handleEvent(Event:new("FloNovelProbeNext"))
        if tiny.rolling.current_page == previous_page then same_page = same_page + 1 end
        check("tiny_next_" .. index, tiny_map:from_xpointer(tiny.rolling:getLastProgress()) == expected,
            { error = tiny.flonovel.navigation_error })
    end
    check("same_screen_subdivisions_were_exercised", same_page > 1, same_page)
    for index = #oracle.tiny_breakpoints - 1, 1, -1 do
        tiny:handleEvent(Event:new("FloNovelProbePrevious"))
        check("tiny_previous_" .. index, tiny_map:from_xpointer(tiny.rolling:getLastProgress()) == oracle.tiny_breakpoints[index])
    end
end
output.tiny_same_page_jumps = same_page
tiny:onClose()
output.total, output.failed = #output.tests, 0
for _, result in ipairs(output.tests) do if not result.passed then output.failed = output.failed + 1 end end
output.passed = output.total - output.failed
output.mapper = bulk_mode and "optional_bulk" or "reference"
local file = assert(io.open(root .. "/" .. result_prefix .. "long-reader-results.json", "wb"))
file:write(json.encode(output)); file:close()
print(string.format("LONG_READER_CHECKS total=%d passed=%d failed=%d", output.total, output.passed, output.failed))
os.exit(output.failed == 0 and 0 or 1)
